/* ManifestFileMapper.selectMasterTempList : 임시마스터 리스트 */
SELECT mod.GROUP_NAME ,mod.MBL_NO ,mod.LINE_CODE ,mod.VESSEL_FLIGHT ,mod.OB_DATE ,mod.OB_TIME ,mod.DEST_CODE ,mod.SERVICE_CODE ,mod.RUN_TYPE ,mod.SEQ_NO_ID ,mod.REGISTER_DATE_TIME FROM TB_ECM_MASTER_TEMP mod WHERE 1 = 1
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND mod.BOUND = #{bound}
AND mod.BOUND_TYPE = #{boundType}

