/* ManifestFileMapper.updateOrderExclusion : 개인통관부호 엑셀업로드시 오더 업데이트 */
UPDATE TB_ECM_OD SET
	   ECM_TYPE = #{ECM_TYPE}

	  ,URL = ''

	  ,CUSTOMS_ID = #{CUSTOMS_ID}
	  ,CD_USE_TYPE = #{CD_USE_TYPE}
	  ,CONSIGNEE_ADDRESS_LOC = ISNULL(CAST(#{CONSIGNEE_ADDRESS_LOC} AS NVARCHAR(300)), '')
	  ,CONSIGNEE_NAME_LOC = #{CONSIGNEE_NAME_LOC}
	  ,CONSIGNEE_HP = #{CONSIGNEE_HP}
	  ,CONSIGNEE_ZIPCODE = #{CONSIGNEE_ZIPCODE}
WHERE OD_JOB_NO = #{OD_JOB_NO}

mapper.insert:
/* ManifestFileMapper.insertExclusion : 적하목록 배제리스트 엑셀업로드 */
MERGE TB_CD_B_INFO AS A 
USING (SELECT #{HBL_NO} AS HBL_NO) AS B 
ON (A.HBL_NO = B.HBL_NO)
WHEN MATCHED THEN
UPDATE SET
	   HBL_NO = #{HBL_NO}
	  ,F_CODE = #{F_CODE}
	  ,OLD_COMMODITY_ITEM = #{OLD_COMMODITY_ITEM}
	  ,NEW_COMMODITY_ITEM = #{NEW_COMMODITY_ITEM}
	  ,CONSIGNEE_NAME = #{CONSIGNEE_NAME}
	  ,CONSIGNEE_HP = #{CONSIGNEE_HP}
	  ,CONSIGNEE_ADDRESS = #{CONSIGNEE_ADDRESS}
	  ,ALLOWED_ITEM_CODE = #{ALLOWED_ITEM_CODE}
	  ,URL = #{URL}
	  ,AMOUNT_CUR = #{AMOUNT_CUR}
	  ,CURRENCY_CODE = #{CURRENCY_CODE}
	  ,CUSTOMS_ID = #{CUSTOMS_ID}
	  ,CD_USE_TYPE = #{CD_USE_TYPE}
	  ,CONSIGNEE_ADDRESS_LOC = ISNULL(CAST(#{CONSIGNEE_ADDRESS_LOC} AS NVARCHAR(300)), '')
	  ,CONSIGNEE_NAME_LOC = #{CONSIGNEE_NAME_LOC}
	  ,CONSENT = #{CONSENT}
	  ,CUSTOMS_UPDATE_YN = 'Y'
	  ,CONSIGNEE_ZIPCODE = #{CONSIGNEE_ZIPCODE}
	  ,UPDATE_USER_ID = #{userId}
	  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
WHEN NOT MATCHED BY TARGET THEN
INSERT(
	   HBL_NO
	  ,F_CODE
	  ,OLD_COMMODITY_ITEM
	  ,NEW_COMMODITY_ITEM
	  ,CONSIGNEE_NAME
	  ,CONSIGNEE_HP
	  ,CONSIGNEE_ADDRESS
	  ,ALLOWED_ITEM_CODE
	  ,URL
	  ,AMOUNT_CUR
	  ,CURRENCY_CODE
	  ,CUSTOMS_ID
	  ,CD_USE_TYPE
	  ,CONSIGNEE_ADDRESS_LOC
	  ,CONSIGNEE_NAME_LOC
	  ,CONSENT
	  ,REMOVE
	  ,CUSTOMS_UPDATE_YN
	  ,CONSIGNEE_ZIPCODE
	  ,REGISTER_USER_ID
	  ,REGISTER_DATE_TIME
	  ,UPDATE_USER_ID
	  ,UPDATE_DATE_TIME
)VALUES(
	   #{HBL_NO}
	  ,#{F_CODE}
	  ,#{OLD_COMMODITY_ITEM}
	  ,#{NEW_COMMODITY_ITEM}
	  ,#{CONSIGNEE_NAME}
	  ,#{CONSIGNEE_HP}
	  ,#{CONSIGNEE_ADDRESS}
	  ,#{ALLOWED_ITEM_CODE}
	  ,#{URL}
	  ,#{AMOUNT_CUR}
	  ,#{CURRENCY_CODE}
	  ,#{CUSTOMS_ID}
	  ,#{CD_USE_TYPE}
	  ,ISNULL(CAST(#{CONSIGNEE_ADDRESS_LOC} AS NVARCHAR(300)), '')
	  ,#{CONSIGNEE_NAME_LOC}
	  ,#{CONSENT}
	  ,''
	  ,'Y'
	  ,#{CONSIGNEE_ZIPCODE}
	  ,#{userId}
	  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	  ,#{userId}
	  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
);

