/* ManifestFileMapper.selectUpsBasic : 적하목록 파일업로드 UPS기초데이터 조회 */
SELECT
	 ETC1
	,ETC2
	,BASIC_TYPE
FROM TB_UPS_BASIC
WHERE BOUND = #{srchBound}
AND BOUND_TYPE = #{srchBoundType}

AND BASIC_TYPE = #{srchBasicType}

		AND ETC2 = 'A'




AND BASIC_TYPE IN(#{item})
AND ETC2 = 'A'


AND ETC1 = #{srchEtc1}


AND ETC2 = #{srchEtc2}


AND ETC1 IN(#{item})


AND ETC2 IN(#{item})


${sortStr}

/* ManifestFileMapper.selectUpsBasicMap : 적하목록 파일업로드 UPS기초데이터 조회 */
SELECT
	 ETC1
	,ETC2
	,ETC3
	,HBL_NO
	,BOUND
FROM TB_UPS_BASIC
WHERE BOUND = #{srchBound}
AND BOUND_TYPE = #{srchBoundType}

AND BASIC_TYPE = #{srchBasicType}

		AND ETC2 = 'A'




AND BASIC_TYPE IN(#{item})
AND ETC2 = 'A'


AND ETC1 = #{srchEtc1}


AND ETC2 = #{srchEtc2}


AND HBL_NO = #{srchHblNo}


AND ETC1 IN(#{item})


AND ETC2 IN(#{item})


${sortStr}

/* ManifestFileMapper.selectUpsBound : TB_UPS_BOUND 조회 */
SELECT TOP 1
	 GROUP_NAME
FROM TB_UPS_BOUND
WHERE BOUND = #{srchBound}
AND BOUND_TYPE = #{srchBoundType}

AND COUNTRY_CODE = #{srchCountryCode}


AND CITY_PORT IN(#{item})

		/* ManifestFileMapper.selectUpsGroup : 적하목록 파일업로드 UPS기초데이터 조회 */
		SELECT TOP 1
			 ups.MBL_NO
			,ups.DEST_CODE
			,ups.OB_DATE
			,ups.OB_TIME
			,ups.LINE_CODE
			,ups.VESSEL_FLIGHT
			,code.NAME_ENG AS DEST_NAME
			,code.ETC2 AS DEST_COUNTRY
		FROM TB_ECM_MASTER_TEMP ups
			 LEFT JOIN TB_SMS_CODE_DETAIL code
			 		   ON code.ENT_CODE = #{srchEntCode}
			 		   AND code.CODE = ups.DEST_CODE
			 		   AND code.GROUP_CODE = 'CITY_PORT'


			WHERE ups.SEQ_NO_ID = #{seqNoId}


			WHERE ups.BOUND = #{srchBound}
			AND ups.BOUND_TYPE = #{srchBoundType}

			AND ups.GROUP_NAME = #{srchGroupName}


			AND ups.RUN_TYPE = #{srchRunType}


			AND ISNULL(ups.SERVICE_CODE,'') IN(#{item})


            AND CONCAT(OB_DATE,' ',OB_TIME, ':00' ) > #{currentDate}


			${sortStr}

/* ManifestFileMapper.selectOrderCustomsId : 오더 통관고유부호 조회 */ IF ( SELECT COUNT(*) FROM TB_ECM_OD od INNER JOIN TB_CD_B_INFO cd ON cd.HBL_NO = od.HBL_NO AND cd.CONSENT = 'Y' WHERE od.AR_DATE >= CONVERT(DATE, #{beforeOneYear}, 23) AND od.AR_DATE <= CONVERT(DATE, #{nowDate}, 23) AND ISNULL(od.CUSTOMS_ID, '') != '' AND dbo.func_AlphabetRemain(od.CONSIGNEE_NAME) = #{consigneeName} ) > 0 BEGIN SELECT TOP 1 od.CUSTOMS_ID ,od.CUSTOMS_ID_TYPE ,CONCAT(ISNULL(od.MRN, ''), ISNULL(od.MSN, ''), ISNULL(od.HSN, '')) AS LC_NO FROM TB_ECM_OD od INNER JOIN TB_CD_B_INFO cd ON cd.HBL_NO = od.HBL_NO ANd cd.CONSENT = 'Y' WHERE od.AR_DATE >= CONVERT(DATE, #{beforeOneYear}, 23) AND od.AR_DATE <= CONVERT(DATE, #{nowDate}, 23) AND ISNULL(od.CUSTOMS_ID, '') != '' AND dbo.func_AlphabetRemain(od.CONSIGNEE_NAME) = #{consigneeName} AND ( RIGHT(dbo.func_getNumeric(od.CONSIGNEE_TEL) ,8) = #{consigneeTel}
OR RIGHT(dbo.func_getNumeric(od.CONSIGNEE_HP) ,8) = #{consigneeHp}
OR RIGHT(dbo.func_getNumeric(od.CONSIGNEE_HP) ,8) = #{consigneeTel}
) ORDER BY od.AR_DATE DESC END

/* ManifestFileMapper.selectMasterInfo2 : 적하목록 파일업로드 마스터조회 */ SELECT mod.MBL_NO ,mod.OD_JOB_NO ,mod.MRN ,mod.MSN ,mod.LINE_CODE ,mod.VESSEL_FLIGHT ,mod.DEST_CODE ,mod.ORIG_CODE ,mod.AR_DATE ,mod.AR_TIME ,mod.OB_DATE ,mod.OB_TIME ,mod.ORIG_NAME ,mod.ORIG_COUNTRY ,mod.DEST_NAME ,mod.DEST_COUNTRY ,mod.CUSTOMS_CODE ,mod.CUSTOMS_DPT_CODE ,mod.VENDER_ID_1 AS VENDER_ID ,mod.FINISH_YN ,mad.EDI_MAILBOX_SEQ_NO
,(SELECT MAX(HSN) FROM TB_ECM_OD WHERE MASTER_OD_JOB_NO = mod.OD_JOB_NO) AS HSN
,mod.CUST_CODE_LV1 ,mod.SHIPPER_COUNTRY_CODE ,mod.CONSIGNEE_COUNTRY_CODE FROM TB_ECM_OD mod INNER JOIN TB_ECM_OD_ADDITIONAL mad ON mad.OD_JOB_NO = mod.OD_JOB_NO WHERE mod.MBL_NO = #{mblNo} AND mod.BOUND = #{bound} AND mod.BOUND_TYPE = #{boundType} AND mod.BL_TYPE_MH = 'M'

/* ManifestFileMapper.selectHouseInfoList : 적하목록 파일업로드 하우스조회 */
SELECT
	 od.HBL_NO
FROM TB_ECM_OD od
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}


AND od.HBL_NO IN(#{item})


AND od.HBL_NO = #{hblNo}

	/* ManifestFileMapper.selectBusEdiCodeInfo : TB_SMS_ENT_BUS_EDI_CODE 조회 */
		SELECT TOP 1
 			 MAX(EDI_SELECTOR_USER_ID) AS EDI_SELECTOR_USER_ID
 			,MAX(EDI_CONFIRMER_USER_ID) AS EDI_CONFIRMER_USER_ID
 			,MAX(CASE WHEN DOCUMENT_YN = 'Y' THEN LTRIM(RTRIM(EDI_EXPRESS_SIGN)) END) AS EDI_EXPRESS_SIGN_DOCUMENT_Y
 			,MAX(CASE WHEN ISNULL(DOCUMENT_YN, 'N') = 'N' THEN LTRIM(RTRIM(EDI_EXPRESS_SIGN)) END) AS EDI_EXPRESS_SIGN_DOCUMENT_N
 			,CONVERT(VARCHAR, DATEADD(DAY, -365, GETDATE()), 23) AS BEFORE_ONE_YEAR
 			,CONVERT(VARCHAR, GETDATE(), 23) AS NOW_DATE
 		FROM TB_SMS_ENT_BUS_EDI_CODE
		WHERE ENT_CODE = #{srchEntCode}
		AND ENT_BUSINESS_CODE = #{srchEntBusinessCode}
		AND BOUND = #{srchBound}
		AND EDI_CITY_PORT = #{srchEdiCityPort}

/* ManifestFileMapper.selectMasterTempGroupName : 임시마스터 그룹명 리스트 */
SELECT GROUP_NAME 
FROM TB_UPS_BOUND 
WHERE BOUND = #{bound} 
AND BOUND_TYPE = #{boundType} 
GROUP BY GROUP_NAME

