/* ManifestFileMapper.selectTsHouseInList : UPS : 항공수입 T/S HAWB 가져오기 - 항공수입 T/S HAWB 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO AS IMP_OD_JOB_NO , od.AR_DATE , od.PO_DATE , od.MBL_NO AS IMP_MBL_NO , od.HBL_NO , od.MRN , od.MSN , od.HSN , od.REMARKS , od.VESSEL_FLIGHT , od.ORIG_CODE , od.CD_TYPE , od.AMOUNT_CUR , od.AMOUNT_LOC , od.AMOUNT_USD , od.DOCUMENT_YN , expOd.MASTER_OD_JOB_NO AS EXP_MASTER_OD_JOB_NO , expOd.OD_JOB_NO AS EXP_OD_JOB_NO , expOd.MBL_NO AS EXP_MBL_NO , CASE WHEN ISNULL(expOd.OD_JOB_NO, '') != '' THEN 'Y' ELSE 'N' END AS EXP_YN FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO LEFT JOIN ( SELECT MASTER_OD_JOB_NO , OD_JOB_NO , MBL_NO , HBL_NO FROM TB_ECM_OD WHERE BOUND = 'AIR' AND BOUND_TYPE = 'EXP' AND BL_TYPE_IERT = 'R' ) expOd ON od.HBL_NO = expOd.HBL_NO WHERE od.BL_TYPE_MH = 'H' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BL_TYPE_IERT = 'T'
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ISNULL(expOd.OD_JOB_NO, '') != ''
AND ISNULL(expOd.OD_JOB_NO, '') = ''

mapper.update:
